export type TranslationKey = keyof typeof messages

export function useLocale() {
  const locale = useState<AppLocale>('constella-locale', () => {
    if (import.meta.client) {
      const saved = localStorage.getItem('constella-locale')
      if (supportedLocales.includes(saved as AppLocale)) return saved as AppLocale
      const browserLocale = navigator.language.split('-')[0] as AppLocale
      if (supportedLocales.includes(browserLocale)) return browserLocale
    }
    return 'uk'
  })

  if (import.meta.client) document.documentElement.lang = locale.value

  const setLocale = (next: AppLocale) => {
    locale.value = next
    if (import.meta.client) {
      localStorage.setItem('constella-locale', next)
      document.documentElement.lang = next
    }
  }

  const t = (key: TranslationKey, values?: Record<string, string | number>) => {
    const index = supportedLocales.indexOf(locale.value)
    const template = messages[key][index] || messages[key][1]
    return template.replace(/\{(\w+)\}/g, (match, name: string) => String(values?.[name] ?? match))
  }

  return { locale, localeNames, setLocale, supportedLocales, t }
}
